write_record(gratz_file,'Gratz v. Bollinger','02-516','2003-06-23','Current jurisdiction sustained, 7–2; current-program approval reversed on constitutional and distinct statutory grounds by five votes; identified earlier and immunity dispositions preserved; remand.',gratz_kernel,gratz_holds,gratz_blocks,161)

